+static conversation_type str_to_convtype_enum(const char* type) {
+    const wslua_conv_types_t* ts;
+    for (ts = convtype_enums; ts->str; ts++) {
+        if ( g_str_equal(ts->str,type) ) {
+            return ts->id;
+        }
+    }
